1967 e2e/specs/acceptance.spec.ts
import { test, expect } from '@playwright/test';
import * as ui from '../support/ui';

test.setTimeout(240_000);
test.describe("policy viewer", () => {
  test("policy viewer", { tag: '@functionality' }, async ({ browser }) => {
    const sheet = ui.sheetId();
    const pg_uma = await ui.userPage(browser, "uma", sheet);
    await ui.setToday(pg_uma, "2026-03-01");
    expect(await ui.setRate(pg_uma, {"grade": "A", "pct": "10.00"})).toBe(true);
    const p_ada = ui.must(await ui.addPerson(pg_uma, {"name": "Ada", "grade": "A"}));
    await ui.setSetting(pg_uma, "floor", "2.00");
    expect(await ui.setSettingDated(pg_uma, "terms", "5", "2026-03-10", "14")).toBe(true);
    expect(await ui.setSettingDated(pg_uma, "rounding", "half-up", "2026-02-01", "half-up")).toBe(true);
    const c_ada_0 = ui.must(await ui.addClaim(pg_uma, p_ada, {"amount": "10.00", "date": "2026-02-20"}));
    const c_ada_1 = ui.must(await ui.addClaim(pg_uma, p_ada, {"amount": "20.00"}));
    const c_ada_2 = ui.must(await ui.addClaim(pg_uma, p_ada, {"amount": "30.00", "date": "2026-03-10"}));
    expect(await ui.claimAction(pg_uma, c_ada_0, "open")).toBe(true);
